function demoMain(idx,label){
  var cfgs=[["3 nodes","partition a-b"],["5 nodes","slow link"],["2 nodes","crash one"]];
  var c=cfgs[idx%cfgs.length];
  return "["+label+"] simulated "+c[0]+" with "+c[1]+": consistency held, 0 data loss";
}

